use system.collections.map
use system.fs
use system.os

fn strip_cr(line String) String
    if line.ends_with("\r")
        return line.substring(0, line.length() - 1)
    line

// True when adding value to total would leave the signed 64-bit range.
fn would_overflow(total int, value int) bool
    let max = 9223372036854775807
    if value > 0
        return total > max - value
    if value < 0
        return total < -max - 1 - value
    false

fn record(totals Map<String, int>, overflowed Map<String, bool>, key String, value int)
    if overflowed.contains_key(key)
        return
    match totals.get(key)
        Some(total):
            if would_overflow(total, value)
                overflowed.set(key, true)
            else
                totals.set(key, total + value)
        None: totals.set(key, value)

fn answer(text String)
    let totals = Map<String, int>()
    let overflowed = Map<String, bool>()
    var in_queries = false
    for raw in text.split("\n")
        let line = strip_cr(raw)
        if line.is_empty()
            in_queries = true
        else if !in_queries
            let parts = line.split(" ")
            if parts.length() != 2
                panic(f"malformed record: {line}")
            match parts[1].to_int()
                Some(value): record(totals, overflowed, parts[0], value)
                None: panic(f"malformed value: {line}")
        else if overflowed.contains_key(line)
            println(f"{line}=overflow")
        else
            match totals.get(line)
                Some(total): println(f"{line}={total}")
                None: println(f"{line}=absent")

fn main()
    let args = Args()
    if args.length() == 0
        panic("usage: main <file>")
    let fs = Fs()
    match fs.read_file(args.element_at(0))
        Result.Ok(text): answer(text)
        Result.Err: panic(f"cannot read {args.element_at(0)}")

