mkdir -p /tmp/jobref && cat > /tmp/jobref/ref.py <<'EOF'
import sys
MAX=2**63-1; MIN=-2**63
text=open(sys.argv[1],encoding='utf-8').read()
lines=text.split('\n')
tot={}; ov=set(); inq=False
out=[]
for raw in lines:
    line=raw[:-1] if raw.endswith('\r') else raw
    if line=='': inq=True; continue
    if inq:
        if line in ov: out.append(f'{line}=overflow')
        elif line in tot: out.append(f'{line}={tot[line]}')
        else: out.append(f'{line}=absent')
    else:
        k,v=line.split(' '); v=int(v)
        if k in ov: continue
        if k not in tot: tot[k]=v; continue
        s=tot[k]+v
        if MIN<=s<=MAX: tot[k]=s
        else: ov.add(k)
print('\n'.join(out)+('\n' if out else ''), end='')
EOF
