import random
random.seed(7)
M=2**63-1; m=-2**63
def rv(): 
    c=random.random()
    if c<0.2: return random.choice([M,m,M-1,m+1,0,1,-1])
    return random.randint(m,M)
for i in range(60):
    recs=[]
    for _ in range(random.randint(0,12)):
        recs.append(f'{random.choice(["a","b","ключ","x y"[0:1],"日"])} {rv()}')
    qs=[random.choice(["a","b","ключ","日","zz"]) for _ in range(random.randint(0,5))]
    s='\n'.join(recs)
    if qs or recs: s+= '\n\n' + '\n'.join(qs) + ('\n' if qs else '')
    open(f'/tmp/jobtests/r{i}','w',encoding='utf-8').write(s)
EOF
